// Summarises today's orders (Asia/Dhaka). Expected columns in the Orders tab:
// Date (ISO or YYYY-MM-DD...), OrderID, Product (or Items), Qty, Total, Status
// Change STATUS_COUNTED to include/exclude statuses (e.g. only 'Paid').
const STATUS_COUNTED = ['Pending', 'Paid', 'Delivered'];
const CURRENCY = 'BDT';

const fmtDay = (d) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Dhaka' }).format(d); // YYYY-MM-DD
const today = fmtDay(new Date());

const rows = $input.all().map((i) => i.json).filter((r) => r.OrderID);
const dayOf = (v) => {
  if (!v) return '';
  const d = new Date(v);
  return isNaN(d) ? String(v).slice(0, 10) : fmtDay(d);
};
const todays = rows.filter((r) => dayOf(r.Date) === today && (!r.Status || STATUS_COUNTED.includes(r.Status)));

const num = (v) => parseFloat(String(v ?? '').replace(/,/g, '')) || 0;
const revenue = todays.reduce((s, r) => s + num(r.Total), 0);
const byProduct = {};
for (const r of todays) {
  const p = r.Product || r.Items || 'Other';
  byProduct[p] = byProduct[p] || { qty: 0, revenue: 0 };
  byProduct[p].qty += num(r.Qty) || 1;
  byProduct[p].revenue += num(r.Total);
}
const top = Object.entries(byProduct).sort((a, b) => b[1].revenue - a[1].revenue).slice(0, 5);
const avg = todays.length ? revenue / todays.length : 0;

const lines = [
  `Daily sales report - ${today}`,
  `Orders: ${todays.length}`,
  `Revenue: ${CURRENCY} ${revenue.toLocaleString('en-US')}`,
  `Average order: ${CURRENCY} ${Math.round(avg).toLocaleString('en-US')}`,
];
if (top.length) {
  lines.push('', 'Top products:');
  top.forEach(([p, v], i) => lines.push(`${i + 1}. ${p} - ${v.qty} pcs, ${CURRENCY} ${v.revenue.toLocaleString('en-US')}`));
} else {
  lines.push('', 'No orders today.');
}
const text = lines.join('\n');
const html = '<pre style="font-family:monospace;font-size:14px">' + text.replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</pre>';
return [{ json: { date: today, orders: todays.length, revenue, subject: `Sales report ${today}: ${CURRENCY} ${revenue}`, text, html } }];
